-- 3. 游戏分类新闻（55 条）
-- ------------------------------------------------------------
SET @game_cat_id = (SELECT `id` FROM `news_category` WHERE `name` = '游戏');


-- ------------------------------------------------------------
-- 4. 相关新闻：每篇新闻随机关联同分类的 3 篇其他新闻
-- ------------------------------------------------------------
SELECT news_id, related_news_id FROM (
  SELECT x.news_id, x.related_news_id,
         ROW_NUMBER() OVER (PARTITION BY x.news_id ORDER BY x.rnd
                            ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS rn
  FROM (
    SELECT n1.id AS news_id, n2.id AS related_news_id, RAND() AS rnd
    FROM news n1
    JOIN news n2 ON n2.category_id = n1.category_id AND n2.id <> n1.id
  ) x
) t
WHERE rn <= 3;

-- ------------------------------------------------------------
-- 5. 收藏：每个用户随机收藏 25 篇新闻
-- ------------------------------------------------------------
SELECT user_id, news_id FROM (
  SELECT x.user_id, x.news_id,
         ROW_NUMBER() OVER (PARTITION BY x.user_id ORDER BY x.rnd
                            ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS rn
  FROM (
    SELECT u.id AS user_id, n.id AS news_id, RAND() AS rnd
    FROM `user` u
    JOIN news n
  ) x
) t
WHERE rn <= 25;

-- ------------------------------------------------------------
-- 6. 浏览历史：每个用户随机浏览 50 篇新闻，时间分布在最近 30 天
-- ------------------------------------------------------------
SELECT user_id, news_id, DATE_SUB(NOW(), INTERVAL FLOOR(RAND() * 30) DAY)
FROM (
  SELECT x.user_id, x.news_id,
         ROW_NUMBER() OVER (PARTITION BY x.user_id ORDER BY x.rnd
                            ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS rn
  FROM (
    SELECT u.id AS user_id, n.id AS news_id, RAND() AS rnd
    FROM `user` u
    JOIN news n
  ) x
) t
WHERE rn <= 50;

